Yes — here is a tiny game you can play in a web browser.

Ask a grown-up to help you do these steps:

1. Open **Notepad** or **TextEdit**.
2. Copy all this code into it.
3. Save it as **cat-fish-game.html**
4. Double-click the file to play.

```html
<!DOCTYPE html>
<html>
<head>
  <title>Cat Catches Fish</title>
  <style>
    body {
      margin: 0;
      background: skyblue;
      text-align: center;
      font-family: Arial, sans-serif;
    }

    canvas {
      background: linear-gradient(skyblue, lightgreen);
      display: block;
      margin: 20px auto;
      border: 4px solid white;
    }
  </style>
</head>
<body>
  <h1>Cat Catches Fish 🐱🐟</h1>
  <p>Use the left and right arrow keys to move!</p>
  <canvas id="game" width="500" height="400"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    let cat = {
      x: 220,
      y: 340,
      width: 60,
      height: 40,
      speed: 6
    };

    let fish = {
      x: Math.random() * 460,
      y: 0,
      width: 40,
      height: 25,
      speed: 3
    };

    let score = 0;
    let leftPressed = false;
    let rightPressed = false;

    document.addEventListener("keydown", function(event) {
      if (event.key === "ArrowLeft") leftPressed = true;
      if (event.key === "ArrowRight") rightPressed = true;
    });

    document.addEventListener("keyup", function(event) {
      if (event.key === "ArrowLeft") leftPressed = false;
      if (event.key === "ArrowRight") rightPressed = false;
    });

    function meow() {
      const sound = new Audio("https://actions.google.com/sounds/v1/animals/cat_meow.ogg");
      sound.play();
    }

    function drawCat() {
      ctx.font = "40px Arial";
      ctx.fillText("🐱", cat.x, cat.y + 35);
    }

    function drawFish() {
      ctx.font = "30px Arial";
      ctx.fillText("🐟", fish.x, fish.y + 25);
    }

    function drawScore() {
      ctx.fillStyle = "black";
      ctx.font = "24px Arial";
      ctx.fillText("Score: " + score, 20, 30);
    }

    function update() {
      if (leftPressed && cat.x > 0) {
        cat.x -= cat.speed;
      }

      if (rightPressed && cat.x < canvas.width - cat.width) {
        cat.x += cat.speed;
      }

      fish.y += fish.speed;

      // Did the cat catch the fish?
      if (
        fish.x < cat.x + cat.width &&
        fish.x + fish.width > cat.x &&
        fish.y < cat.y + cat.height &&
        fish.y + fish.height > cat.y
      ) {
        score += 1;
        meow();
        fish.x = Math.random() * 460;
        fish.y = 0;
        fish.speed += 0.2;
      }

      // If fish falls past the cat, start it again
      if (fish.y > canvas.height) {
        fish.x = Math.random() * 460;
        fish.y = 0;
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawScore();
      drawCat();
      drawFish();
    }

    function gameLoop() {
      update();
      draw();
      requestAnimationFrame(gameLoop);
    }

    gameLoop();
  </script>
</body>
</html>
```

You made the main rule: **catch fish = get a point + meow**. Nice game rule.

After you try it, tell me: **what should happen when the fish hits the ground?**

I can’t make a real web link from here because I can’t upload the game to the internet. But you can still play it with a grown-up’s help using an easy website called **JSFiddle**.

Do this:

1. Ask a grown-up to open this website:  
   **https://jsfiddle.net/**

2. Find the box that says **HTML**.

3. Copy and paste this code into the **HTML** box:

```html
<h1>Cat Catches Fish 🐱🐟</h1>
<p>Use the left and right arrow keys. Catch fish to score. If one hits the ground, you lose a heart!</p>
<canvas id="game" width="500" height="400" style="background:linear-gradient(skyblue,lightgreen); border:4px solid white;"></canvas>

<script>
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

let cat = { x: 220, y: 340, width: 60, height: 40, speed: 6 };
let fish = { x: Math.random() * 460, y: 0, width: 40, height: 25, speed: 3 };

let score = 0;
let hearts = 3;
let leftPressed = false;
let rightPressed = false;
let gameOver = false;

document.addEventListener("keydown", function(event) {
  if (event.key === "ArrowLeft") leftPressed = true;
  if (event.key === "ArrowRight") rightPressed = true;
});

document.addEventListener("keyup", function(event) {
  if (event.key === "ArrowLeft") leftPressed = false;
  if (event.key === "ArrowRight") rightPressed = false;
});

function meow() {
  let sound = new Audio("https://actions.google.com/sounds/v1/animals/cat_meow.ogg");
  sound.play();
}

function resetFish() {
  fish.x = Math.random() * 460;
  fish.y = 0;
}

function update() {
  if (gameOver) return;

  if (leftPressed && cat.x > 0) cat.x -= cat.speed;
  if (rightPressed && cat.x < canvas.width - cat.width) cat.x += cat.speed;

  fish.y += fish.speed;

  if (
    fish.x < cat.x + cat.width &&
    fish.x + fish.width > cat.x &&
    fish.y < cat.y + cat.height &&
    fish.y + fish.height > cat.y
  ) {
    score += 1;
    meow();
    resetFish();
    fish.speed += 0.2;
  }

  if (fish.y > canvas.height) {
    hearts -= 1;
    resetFish();

    if (hearts <= 0) {
      gameOver = true;
    }
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.font = "24px Arial";
  ctx.fillStyle = "black";
  ctx.fillText("Score: " + score, 20, 30);
  ctx.fillText("Hearts: " + "❤️".repeat(hearts), 20, 60);

  ctx.font = "40px Arial";
  ctx.fillText("🐱", cat.x, cat.y + 35);

  ctx.font = "30px Arial";
  ctx.fillText("🐟", fish.x, fish.y + 25);

  if (gameOver) {
    ctx.fillStyle = "rgba(255,255,255,0.8)";
    ctx.fillRect(80, 140, 340, 120);

    ctx.fillStyle = "black";
    ctx.font = "36px Arial";
    ctx.fillText("Game Over!", 150, 190);

    ctx.font = "24px Arial";
    ctx.fillText("Final Score: " + score, 170, 230);
  }
}

function gameLoop() {
  update();
  draw();
  requestAnimationFrame(gameLoop);
}

gameLoop();
</script>
```

4. Press the **Run** button near the top.

You added a good rule: **fish hits ground = lose a heart**. That makes the game more exciting.

After you play, tell me in your own words: **what does the heart rule do in the game?**
